#!/usr/bin/env node
/*
 * Bundles the official brand SVGs in src/brand/svg/ into src/brand/svgs.generated.ts
 * so react-native-svg can render them (SvgXml) on iOS, Android and web with no
 * asset pipeline. The .svg files are the source of truth: each one is the brand's
 * official file run through SVGO (geometry and colours unchanged); provenance and
 * usage rules are in docs/BRAND_ASSETS.md.
 *
 *   node packages/ui/scripts/brand-svgs.mjs          # regenerate
 *   node packages/ui/scripts/brand-svgs.mjs --check  # fail if the generated file is stale
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const BRAND_DIR = resolve(dirname(fileURLToPath(import.meta.url)), "../src/brand");
const SVG_DIR = join(BRAND_DIR, "svg");
const OUT = join(BRAND_DIR, "svgs.generated.ts");

/** Anything that could execute, fetch or embed raster data has no place in a logo. */
const FORBIDDEN =
  /<script|<foreignObject|<image|href="(?!#)|xlink:href="(?!#)|on[a-z]+=|url\((?!#)/i;

export async function buildBrandSvgs() {
  const files = readdirSync(SVG_DIR)
    .filter((f) => f.endsWith(".svg"))
    .sort();
  const entries = files.map((file) => {
    const xml = readFileSync(join(SVG_DIR, file), "utf8").trim();
    if (FORBIDDEN.test(xml)) throw new Error(`${file}: contains a forbidden construct`);
    const viewBox = /viewBox="([^"]+)"/.exec(xml)?.[1];
    if (!viewBox) throw new Error(`${file}: missing viewBox`);
    const [, , w, h] = viewBox.split(/[\s,]+/).map(Number);
    if (!w || !h) throw new Error(`${file}: bad viewBox`);
    return { key: file.slice(0, -4), xml, aspect: Number((w / h).toFixed(4)) };
  });
  const body = entries
    .map(
      (e) =>
        `  ${JSON.stringify(e.key)}: { aspect: ${String(e.aspect)}, xml: ${JSON.stringify(e.xml)} },`,
    )
    .join("\n");
  const source = `/* Generated by packages/ui/scripts/brand-svgs.mjs from src/brand/svg/*.svg. Do not edit. */\nexport const BRAND_SVGS = {\n${body}\n} as const;\n\nexport type BrandSvgKey = keyof typeof BRAND_SVGS;\n`;
  const prettier = await import("prettier");
  const options = (await prettier.resolveConfig(OUT)) ?? {};
  return prettier.format(source, { ...options, filepath: OUT });
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const next = await buildBrandSvgs();
  if (process.argv.includes("--check")) {
    const current = readFileSync(OUT, "utf8");
    if (current !== next) {
      console.error("svgs.generated.ts is stale: run node packages/ui/scripts/brand-svgs.mjs");
      process.exit(1);
    }
  } else {
    writeFileSync(OUT, next);
    console.log(`wrote ${OUT}`);
  }
}
